// Real elevation, Taurene–Brezgi country, Latvia. 8.8 km square,
// 320x320 grid, centre offset (500, 1700) from the village origin.
// Source: AWS Open Data terrain tiles (terrarium), z13, fetched 2026-07-04.
export const HM_GRID = 320;
export const HM_SPAN = 8800;
export const HM_OFF_X = 500;
export const HM_OFF_Z = 1700;
export const HM_B64 = "";
export function decodeHeightmap() {
  const bin = atob(HM_B64);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  const dm = new Int16Array(bytes.buffer);
  const m = new Float32Array(dm.length);
  for (let i = 0; i < dm.length; i++) m[i] = dm[i] / 10;
  return m;
}
